SELECT CASE WHEN units >= 34 THEN 'LARGE' ELSE 'SMALL' END AS units_tier, COUNT(DISTINCT product_id) AS distinct_product_ids, STDDEV_SAMP(revenue) AS revenue_stddev, BIT_OR(units) AS units_bit_or, COUNT(DISTINCT product_id) AS distinct_product_ids_2, STDDEV_SAMP(units) AS units_stddev, BIT_AND(units) AS units_bit_and FROM store_sales GROUP BY CASE WHEN units >= 34 THEN 'LARGE' ELSE 'SMALL' END ORDER BY units_bit_or NULLS LAST;
